import React, { useEffect, useState } from "react";
import Sidebar from "../compornents/Sidebar";
import Header from "../compornents/Header";
import { auth, database } from "../firebaseConfig";
import { ref, get, onValue } from "firebase/database";
import { Link } from "react-router-dom";

const Dashboard = () => {
  const [userData, setUserData] = useState(null);
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);

  //  Fetch current logged-in user data (from users/uid_userX)
  const fetchUserData = async () => {
    if (!auth.currentUser) return;

    const usersRef = ref(database, "users");
    const usersSnapshot = await get(usersRef);

    let foundUser = null;
    let foundUserId = null;

    usersSnapshot.forEach((childSnapshot) => {
      const data = childSnapshot.val();
      if (data.firebaseUid === auth.currentUser.uid) {
        foundUser = data;
        foundUserId = childSnapshot.key;
      }
    });

    if (foundUser) {
      setUserData({ ...foundUser, id: foundUserId });
      return foundUserId;
    } else {
      console.error("User not found in database!");
      return null;
    }
  };

  // 🔹 Fetch reports submitted by this user
  const fetchReports = async (userId) => {
    const reportsRef = ref(database, "breakdowns");
    onValue(reportsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const userReports = Object.entries(data)
          .filter(([_, report]) => report.reporterUid === userId)
          .map(([id, report]) => ({ id, ...report }));
        setReports(userReports);
      } else {
        setReports([]);
      }
      setLoading(false);
    });
  };

  useEffect(() => {
    const loadUserAndReports = async () => {
      const uid = await fetchUserData();
      if (uid) fetchReports(uid);
    };
    loadUserAndReports();
  }, []);

  if (loading)
    return (
      <div className="flex items-center justify-center h-screen bg-gray-900 text-white">
        Loading Dashboard...
      </div>
    );

  return (
    <div className="flex h-screen overflow-hidden bg-gray-900 text-gray-200">
      {/* Sidebar */}
      <aside className="w-64 flex-shrink-0 h-full sticky top-0">
        <Sidebar />
      </aside>

      {/* Main Section */}
      <div className="flex flex-col flex-1 overflow-hidden">
        {/* Header */}
        <header className="sticky top-0 z-10">
          <Header />
        </header>

        {/* Content */}
        <main className="flex-1 p-8 overflow-y-auto bg-gray-900 dark:bg-gray-800">
          <div className="max-w-5xl mx-auto">
            {/*User Info Card */}
            {userData && (
              <div className="bg-gray-800 rounded-xl p-6 mb-8 shadow-md border border-gray-700">
                <h2 className="text-2xl font-bold text-white mb-4">
                  Welcome, {userData.username} 👋
                </h2>
                <div className="text-gray-300 text-sm space-y-1">
                  <p>
                    <span className="font-semibold text-green-400">Email:</span>{" "}
                    {userData.email}
                  </p>
                  <p>
                    <span className="font-semibold text-green-400">Role:</span>{" "}
                    {userData.role}
                  </p>
                  <p>
                    <span className="font-semibold text-green-400">User ID:</span>{" "}
                    {userData.id}
                  </p>
                </div>
              </div>
            )}

            {/* Reports Section */}
            <p className="text-3xl font-bold tracking-tight dark:text-white mb-6">
              Your Submitted Reports
            </p>

            <div className="bg-gray-800 rounded-xl shadow-sm overflow-hidden border border-gray-700">
              <div className="p-4 flex items-center justify-between border-b border-gray-700">
                <input
                  placeholder="Search reports..."
                  className="form-input w-full max-w-xs pl-10 pr-4 py-2 rounded-lg border border-gray-600 bg-gray-700 text-sm text-white focus:ring-green-500 focus:border-green-500"
                />
                <select className="form-select rounded-lg border border-gray-600 bg-gray-700 text-sm text-white focus:ring-green-500 focus:border-green-500">
                  <option>All Statuses</option>
                  <option>Pending</option>
                  <option>In Progress</option>
                  <option>Resolved</option>
                  <option>Rejected</option>
                </select>
              </div>

              {/* Table */}
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-left text-gray-400">
                  <thead className="text-xs uppercase bg-gray-700 text-gray-300">
                    <tr>
                      <th className="px-6 py-3">Report ID</th>
                      <th className="px-6 py-3">System</th>
                      <th className="px-6 py-3">Status</th>
                      <th className="px-6 py-3">Date</th>
                      <th className="px-6 py-3">Details</th>
                    </tr>
                  </thead>
                  <tbody>
                    {reports.length > 0 ? (
                      reports.map((report) => (
                        <tr
                          key={report.id}
                          className="bg-gray-800 border-b border-gray-700 hover:bg-gray-700"
                        >
                          <td className="px-6 py-4 font-medium text-white">
                            {report.id}
                          </td>
                          <td className="px-6 py-4 text-gray-300">
                            {report.itemName}
                          </td>
                          <td className="px-6 py-4">
                            <span
                              className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                report.status === "resolved"
                                  ? "bg-green-900 text-green-300"
                                  : report.status === "pending"
                                  ? "bg-yellow-900 text-yellow-300"
                                  : "bg-gray-600 text-gray-200"
                              }`}
                            >
                              {report.status}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-gray-400">
                            {new Date(
                              report.timestamps?.created
                            ).toLocaleString() || "-"}
                          </td>
                        
                        </tr>
                        
                      ))
                    ) : (
                      <tr>
                        <td
                          colSpan="4"
                          className="px-6 py-6 text-center text-gray-400"
                        >
                          No reports found.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;
